 function filterBar(parent,items,render){const r=node('div',undefined,'tw-filters');let selected='all';const search=node('input');search.type='search';search.placeholder='Buscar taller…';search.setAttribute('aria-label','Buscar taller');const tabs=node('div',undefined,'tw-tabs');const controls=items.map(([key,label])=>{const b=btn(label,()=>{selected=key;draw();});tabs.append(b);return [key,b];});function draw(){controls.forEach(([key,b])=>b.setAttribute('aria-pressed',String(selected===key)));render(selected,search.value.trim().toLocaleLowerCase('es-MX'));}search.oninput=draw;r.append(tabs,search);parent.append(r);return draw;}
