 function reset(){if(current){const a=current;current=null;clearInterval(timer);if(navigator.onLine&&profile===a.owner)void rpc('interrupt',{attempt:a.id}).catch(()=>{});}loginOwner=null;unread=0;lastNotices.clear();clear();}
