 function heading(title,description='Gestión y seguimiento de capacitación'){const r=row();r.classList.add('tw-heading');const intro=node('div',undefined,'tw-intro');intro.append(node('span','MARC / CAPACITACIÓN','tw-eyebrow'),node('h1',title),node('p',description));r.append(intro);return r;}
 async function load(){if(loading||current||active!=='talleres140'||!profile)return;const p=profile,g=++generation;loading=true;host().replaceChildren(node('p','Consultando talleres…','notice'));try{if(p.rol==='administrador'){const data=await rpc('admin_list');if(!valid(g,p))return;catalog=data;admin();}else{await login(p);const data=await rpc('list');if(!valid(g,p))return;participant(data);}}catch(e){if(valid(g,p))host().replaceChildren(node('p','No se pudieron consultar talleres: '+fail(e),'notice'),btn('Reintentar',load));}finally{if(g===generation)loading=false;}}
 function table140(headers,rows){const wrap=node('div',undefined,'table-wrap');wrap.style.overflowX='auto';const t=node('table'),head=node('thead'),r=node('tr');headers.forEach(h=>r.append(node('th',h)));head.append(r);t.append(head);const body=node('tbody');for(const cells of rows){const tr=node('tr');for(const v of cells){const td=node('td');td.append(v instanceof Node?v:document.createTextNode(String(v??'—')));tr.append(td);}body.append(tr);}t.append(body);wrap.append(t);return wrap;}
